ALL.append(q(126,"Easy","What is the subject complement? 'Maria is the class president.'",["Maria","is","the class president","class"],"the class president","After 'is,' 'the class president' renames 'Maria.'",["subject complement","predicate nominative"]))
ALL.append(q(127,"Easy","What is the subject complement? 'The road appears dangerous at night.'",["road","appears","dangerous","night"],"dangerous","After the linking verb 'appears,' 'dangerous' describes 'road.'",["subject complement","predicate adjective"]))
ALL.append(q(128,"Easy","What is the subject complement? 'He is my best friend.'",["He","is","my best friend","best"],"my best friend","After 'is,' 'my best friend' renames 'He.'",["subject complement","predicate nominative"]))
ALL.append(q(129,"Easy","What is the subject complement? 'The milk turned sour overnight.'",["milk","turned","sour","overnight"],"sour","After the linking verb 'turned,' 'sour' describes 'milk.'",["subject complement","predicate adjective"]))
ALL.append(q(130,"Easy","What is the subject complement? 'She remained silent throughout the meeting.'",["She","remained","silent","meeting"],"silent","After the linking verb 'remained,' 'silent' describes 'She.'",["subject complement","predicate adjective"]))

# --- Complete Sentence vs. Fragment (Easy 131-160) ---
ALL.append(q(131,"Easy","Which of the following is a complete sentence?",["Running quickly through the hallway.","The new policy regarding overtime.","The employee submitted the report on time.","Because the meeting was cancelled."],"The employee submitted the report on time.","It has a subject (employee), a verb (submitted), and expresses a complete thought.",["complete sentence","fragment","identification"]))
ALL.append(q(132,"Easy","Which of the following is a complete sentence?",["Although the deadline was extended.","The manager approved the budget.","Walking to the office every morning.","The documents on the table."],"The manager approved the budget.","It has a subject (manager), a verb (approved), and a complete thought.",["complete sentence","fragment","identification"]))
ALL.append(q(133,"Easy","Which of the following is a sentence fragment?",["She finished the project early.","The birds flew south for the winter.","Because he was late for work.","The committee approved the plan."],"Because he was late for work.","It begins with 'because' (subordinating conjunction), making it a dependent clause — incomplete thought.",["fragment","dependent clause","identification"]))
ALL.append(q(134,"Easy","Which of the following is a sentence fragment?",["The teacher explained the lesson clearly.","Running late for the scheduled meeting.","He passed the civil service exam.","The office closes at five o'clock."],"Running late for the scheduled meeting.","It has no subject and no finite verb — 'running' is a participle, not a complete verb.",["fragment","participial phrase","identification"]))
ALL.append(q(135,"Easy","Which of the following is a sentence fragment?",["The sun set behind the mountains.","They celebrated their anniversary.","The report submitted by the intern.","She answered all the questions."],"The report submitted by the intern.","It has no main verb — 'submitted' here is a past participle modifying 'report,' not a predicate.",["fragment","missing predicate","identification"]))
ALL.append(q(136,"Easy","Which of the following is a complete sentence?",["After the storm passed through the city.","The new employee in the accounting department.","Hoping to finish before the deadline.","The director announced the results."],"The director announced the results.","Subject (director) + verb (announced) + complete thought.",["complete sentence","fragment","identification"]))
ALL.append(q(137,"Easy","Which of the following is a complete sentence?",["Since the policy was implemented last year.","The old building near the park.","The students completed their assignments.","Waiting for the bus in the rain."],"The students completed their assignments.","Subject (students) + verb (completed) + complete thought.",["complete sentence","fragment","identification"]))
ALL.append(q(138,"Easy","Which of the following is a sentence fragment?",["The children played in the garden.","He submitted his application on time.","Although she studied hard for the exam.","The company hired new employees."],"Although she studied hard for the exam.","Begins with 'although' — a dependent clause that cannot stand alone.",["fragment","dependent clause","identification"]))
ALL.append(q(139,"Easy","Which of the following is a sentence fragment?",["The meeting ended early today.","She received a promotion last month.","The proposal written by the committee.","They traveled to Baguio last weekend."],"The proposal written by the committee.","No main verb — 'written' is a participle modifying 'proposal,' not a predicate.",["fragment","missing predicate","identification"]))
ALL.append(q(140,"Easy","Which of the following is a complete sentence?",["While the teacher was explaining the lesson.","The newly hired employees in the office.","Running through the park every morning.","The bus arrived on schedule."],"The bus arrived on schedule.","Subject (bus) + verb (arrived) + complete thought.",["complete sentence","fragment","identification"]))

ALL.append(q(141,"Easy","Which of the following is a complete sentence?",["Because the office was closed for renovation.","The documents filed by the secretary.","Swimming in the pool after class.","The children enjoyed the field trip."],"The children enjoyed the field trip.","Subject (children) + verb (enjoyed) + complete thought.",["complete sentence","fragment","identification"]))
ALL.append(q(142,"Easy","Which of the following is a sentence fragment?",["The manager called a meeting.","She passed the board exam.","The new regulation about employee benefits.","He arrived before the deadline."],"The new regulation about employee benefits.","No verb — it's just a noun phrase with a prepositional phrase modifier.",["fragment","missing predicate","identification"]))
ALL.append(q(143,"Easy","Which of the following is a sentence fragment?",["The team won the competition.","He cleaned the entire office.","Before the supervisor arrived at work.","The report was submitted on time."],"Before the supervisor arrived at work.","Begins with 'before' — a dependent clause that cannot stand alone.",["fragment","dependent clause","identification"]))
ALL.append(q(144,"Easy","Which of the following is a complete sentence?",["When the results were finally announced.","The hardworking student from Quezon City.","Typing the report as fast as possible.","The committee reached a decision."],"The committee reached a decision.","Subject (committee) + verb (reached) + complete thought.",["complete sentence","fragment","identification"]))
ALL.append(q(145,"Easy","Which of the following is a sentence fragment?",["She organized the files efficiently.","The company expanded its operations.","A dedicated public servant with years of experience.","The rain stopped before noon."],"A dedicated public servant with years of experience.","No verb — just a noun phrase. What about this person?",["fragment","missing predicate","identification"]))
ALL.append(q(146,"Easy","Which of the following is a complete sentence?",["If the budget is approved by the board.","The tall man standing near the entrance.","Finishing the project ahead of schedule.","The secretary filed all the documents."],"The secretary filed all the documents.","Subject (secretary) + verb (filed) + complete thought.",["complete sentence","fragment","identification"]))
ALL.append(q(147,"Easy","Which of the following is a sentence fragment?",["The doctor prescribed medicine for the patient.","He completed the training program.","Unless the weather improves by tomorrow.","The store opens at nine every day."],"Unless the weather improves by tomorrow.","Begins with 'unless' — a dependent clause that cannot stand alone.",["fragment","dependent clause","identification"]))
ALL.append(q(148,"Easy","Which of the following is a complete sentence?",["Although the project was completed on time.","The experienced teacher from the province.","Working overtime to meet the deadline.","She received the highest score in the exam."],"She received the highest score in the exam.","Subject (She) + verb (received) + complete thought.",["complete sentence","fragment","identification"]))
ALL.append(q(149,"Easy","Which of the following is a sentence fragment?",["The mayor inaugurated the new building.","They submitted their applications early.","Hoping to get promoted this year.","The office was renovated last month."],"Hoping to get promoted this year.","No subject and no finite verb — 'hoping' is a participle.",["fragment","participial phrase","identification"]))
ALL.append(q(150,"Easy","Which of the following is a complete sentence?",["Since the new policy took effect last month.","The documents prepared by the legal team.","Studying hard for the upcoming examination.","The governor signed the executive order."],"The governor signed the executive order.","Subject (governor) + verb (signed) + complete thought.",["complete sentence","fragment","identification"]))

# --- Indirect Object Identification (Easy 151-170) ---
ALL.append(q(151,"Easy","What is the indirect object? 'She gave her mother a gift.'",["She","gave","her mother","a gift"],"her mother","Gave what? → a gift (DO). Gave to whom? → her mother (IO, between verb and DO).",["indirect object","identification"]))
ALL.append(q(152,"Easy","What is the indirect object? 'The teacher showed the class a video.'",["teacher","showed","the class","a video"],"the class","Showed what? → a video (DO). Showed to whom? → the class (IO).",["indirect object","identification"]))
ALL.append(q(153,"Easy","What is the indirect object? 'He sent his friend a letter.'",["He","sent","his friend","a letter"],"his friend","Sent what? → a letter (DO). Sent to whom? → his friend (IO).",["indirect object","identification"]))
ALL.append(q(154,"Easy","What is the indirect object? 'The manager gave the employees a bonus.'",["manager","gave","the employees","a bonus"],"the employees","Gave what? → a bonus (DO). Gave to whom? → the employees (IO).",["indirect object","identification"]))
ALL.append(q(155,"Easy","What is the indirect object? 'She told him the truth.'",["She","told","him","the truth"],"him","Told what? → the truth (DO). Told to whom? → him (IO).",["indirect object","identification"]))
ALL.append(q(156,"Easy","What is the indirect object? 'The principal awarded the student a medal.'",["principal","awarded","the student","a medal"],"the student","Awarded what? → a medal (DO). Awarded to whom? → the student (IO).",["indirect object","identification"]))
ALL.append(q(157,"Easy","What is the indirect object? 'He bought his daughter a new dress.'",["He","bought","his daughter","a new dress"],"his daughter","Bought what? → a new dress (DO). Bought for whom? → his daughter (IO).",["indirect object","identification"]))
ALL.append(q(158,"Easy","What is the indirect object? 'The librarian lent the student a reference book.'",["librarian","lent","the student","a reference book"],"the student","Lent what? → a reference book (DO). Lent to whom? → the student (IO).",["indirect object","identification"]))
ALL.append(q(159,"Easy","What is the indirect object? 'She offered him a cup of coffee.'",["She","offered","him","a cup of coffee"],"him","Offered what? → a cup of coffee (DO). Offered to whom? → him (IO).",["indirect object","identification"]))
ALL.append(q(160,"Easy","What is the indirect object? 'The coach taught the players a new strategy.'",["coach","taught","the players","a new strategy"],"the players","Taught what? → a new strategy (DO). Taught to whom? → the players (IO).",["indirect object","identification"]))

# --- Sentence Pattern / Verb Type / Mixed (Easy 161-200) ---
ALL.append(q(161,"Easy","What sentence pattern does this follow? 'Birds fly.'",["Subject + Verb + Direct Object","Subject + Linking Verb + Complement","Subject + Verb","Subject + Verb + Indirect Object + Direct Object"],"Subject + Verb","The sentence has only a subject (Birds) and an intransitive verb (fly) — no object needed.",["sentence pattern","S-V"]))
ALL.append(q(162,"Easy","What sentence pattern does this follow? 'She is a nurse.'",["Subject + Verb + Direct Object","Subject + Linking Verb + Complement","Subject + Verb","Subject + Verb + Indirect Object + Direct Object"],"Subject + Linking Verb + Complement","'Is' is a linking verb; 'a nurse' renames the subject.",["sentence pattern","S-LV-SC"]))
ALL.append(q(163,"Easy","What sentence pattern does this follow? 'He kicked the ball.'",["Subject + Verb + Direct Object","Subject + Linking Verb + Complement","Subject + Verb","Subject + Verb + Indirect Object + Direct Object"],"Subject + Verb + Direct Object","'Kicked' is an action verb; 'the ball' receives the action.",["sentence pattern","S-V-DO"]))
ALL.append(q(164,"Easy","What sentence pattern does this follow? 'The baby cried.'",["Subject + Verb + Direct Object","Subject + Linking Verb + Complement","Subject + Verb","Subject + Verb + Indirect Object + Direct Object"],"Subject + Verb","'Cried' is intransitive — no object follows.",["sentence pattern","S-V"]))
ALL.append(q(165,"Easy","What sentence pattern does this follow? 'She gave him a book.'",["Subject + Verb + Direct Object","Subject + Linking Verb + Complement","Subject + Verb","Subject + Verb + Indirect Object + Direct Object"],"Subject + Verb + Indirect Object + Direct Object","'Gave' has an IO (him) and a DO (a book).",["sentence pattern","S-V-IO-DO"]))
ALL.append(q(166,"Easy","What sentence pattern does this follow? 'The food tastes delicious.'",["Subject + Verb + Direct Object","Subject + Linking Verb + Complement","Subject + Verb","Subject + Verb + Indirect Object + Direct Object"],"Subject + Linking Verb + Complement","'Tastes' is a linking verb here; 'delicious' describes the subject.",["sentence pattern","S-LV-SC"]))
ALL.append(q(167,"Easy","What sentence pattern does this follow? 'The dog barked.'",["Subject + Verb + Direct Object","Subject + Linking Verb + Complement","Subject + Verb","Subject + Verb + Indirect Object + Direct Object"],"Subject + Verb","'Barked' is intransitive — no object.",["sentence pattern","S-V"]))
ALL.append(q(168,"Easy","What sentence pattern does this follow? 'He became a teacher.'",["Subject + Verb + Direct Object","Subject + Linking Verb + Complement","Subject + Verb","Subject + Verb + Indirect Object + Direct Object"],"Subject + Linking Verb + Complement","'Became' is a linking verb; 'a teacher' renames the subject.",["sentence pattern","S-LV-SC"]))
ALL.append(q(169,"Easy","What sentence pattern does this follow? 'She read the book.'",["Subject + Verb + Direct Object","Subject + Linking Verb + Complement","Subject + Verb","Subject + Verb + Indirect Object + Direct Object"],"Subject + Verb + Direct Object","'Read' is an action verb; 'the book' is the direct object.",["sentence pattern","S-V-DO"]))
ALL.append(q(170,"Easy","What sentence pattern does this follow? 'The teacher sent the parents a notice.'",["Subject + Verb + Direct Object","Subject + Linking Verb + Complement","Subject + Verb","Subject + Verb + Indirect Object + Direct Object"],"Subject + Verb + Indirect Object + Direct Object","'Sent' has an IO (the parents) and a DO (a notice).",["sentence pattern","S-V-IO-DO"]))
ALL.append(q(171,"Easy","Is 'ran' an action verb or a linking verb in: 'He ran to the store'?",["Action verb","Linking verb","Helping verb","None of the above"],"Action verb","'Ran' expresses physical action. He ≠ store, so it's not linking.",["verb type","action verb"]))
ALL.append(q(172,"Easy","Is 'looks' an action verb or a linking verb in: 'She looks tired'?",["Action verb","Linking verb","Helping verb","None of the above"],"Linking verb","'Looks' connects 'She' to 'tired.' She = tired. It's a linking verb here.",["verb type","linking verb"]))
ALL.append(q(173,"Easy","Is 'grew' an action verb or a linking verb in: 'The plant grew tall'?",["Action verb","Linking verb","Helping verb","None of the above"],"Linking verb","'Grew' connects 'plant' to 'tall.' Plant = tall. Linking verb.",["verb type","linking verb"]))
ALL.append(q(174,"Easy","Is 'grew' an action verb or a linking verb in: 'The farmer grew vegetables'?",["Action verb","Linking verb","Helping verb","None of the above"],"Action verb","'Grew' expresses action here — the farmer cultivated vegetables. Farmer ≠ vegetables.",["verb type","action verb"]))
ALL.append(q(175,"Easy","What is the complete subject? 'The young athlete won the competition.'",["athlete","won","The young athlete","the competition"],"The young athlete","The complete subject includes the simple subject plus all its modifiers: 'The young athlete.'",["complete subject","identification"]))
ALL.append(q(176,"Easy","What is the complete subject? 'A small kitten sat on the porch.'",["kitten","sat","A small kitten","porch"],"A small kitten","The complete subject is 'A small kitten' — the noun with all its modifiers.",["complete subject","identification"]))
ALL.append(q(177,"Easy","What is the complete predicate? 'The children played in the park all afternoon.'",["played","The children","played in the park all afternoon","in the park"],"played in the park all afternoon","The complete predicate is everything after the subject: verb + all modifiers and objects.",["complete predicate","identification"]))
ALL.append(q(178,"Easy","What is the complete predicate? 'She quickly finished her homework.'",["finished","She","quickly finished her homework","her homework"],"quickly finished her homework","Everything after the subject 'She' is the complete predicate.",["complete predicate","identification"]))
ALL.append(q(179,"Easy","What is the implied subject in: 'Close the door, please.'?",["door","please","Close","You (implied)"],"You (implied)","Imperative sentences have an implied subject 'you' — the person being commanded.",["implied subject","imperative"]))
ALL.append(q(180,"Easy","What is the implied subject in: 'Submit your reports before Friday.'?",["reports","Friday","Submit","You (implied)"],"You (implied)","This is a command. The subject 'you' is understood but not stated.",["implied subject","imperative"]))

ALL.append(q(181,"Easy","Which word is the helping verb in: 'She is reading a novel'?",["She","is","reading","novel"],"is","'Is' helps the main verb 'reading' form the present continuous tense.",["helping verb","verb phrase"]))
ALL.append(q(182,"Easy","Which word is the helping verb in: 'They have finished the project'?",["They","have","finished","project"],"have","'Have' helps 'finished' form the present perfect tense.",["helping verb","verb phrase"]))
ALL.append(q(183,"Easy","Which word is the helping verb in: 'He will attend the seminar'?",["He","will","attend","seminar"],"will","'Will' helps 'attend' form the future tense.",["helping verb","verb phrase"]))
ALL.append(q(184,"Easy","Which word is the helping verb in: 'The report was submitted yesterday'?",["report","was","submitted","yesterday"],"was","'Was' helps 'submitted' form the passive voice.",["helping verb","verb phrase"]))
ALL.append(q(185,"Easy","Which word is the helping verb in: 'She can speak three languages'?",["She","can","speak","languages"],"can","'Can' is a modal helping verb that shows ability.",["helping verb","verb phrase","modal"]))
ALL.append(q(186,"Easy","What is the verb phrase in: 'The package has been delivered'?",["package","has been","delivered","has been delivered"],"has been delivered","The verb phrase includes all helping verbs + main verb: has (helper) + been (helper) + delivered (main).",["verb phrase","identification"]))
ALL.append(q(187,"Easy","What is the verb phrase in: 'She will be attending the conference'?",["She","will be","attending","will be attending"],"will be attending","Helping verbs 'will be' + main verb 'attending' = complete verb phrase.",["verb phrase","identification"]))
ALL.append(q(188,"Easy","What is the verb phrase in: 'The documents should have been reviewed'?",["documents","should have been","reviewed","should have been reviewed"],"should have been reviewed","All helping verbs + main verb: should + have + been + reviewed.",["verb phrase","identification"]))
ALL.append(q(189,"Easy","Is this a phrase or a clause? 'in the morning'",["Phrase","Independent clause","Dependent clause","Complete sentence"],"Phrase","It has no subject-verb pair. It's a prepositional phrase.",["phrase","clause","distinction"]))
ALL.append(q(190,"Easy","Is this a phrase or a clause? 'because she was late'",["Phrase","Independent clause","Dependent clause","Complete sentence"],"Dependent clause","It has a subject (she) and verb (was) but begins with 'because' — incomplete thought.",["phrase","clause","distinction"]))
ALL.append(q(191,"Easy","Is this a phrase or a clause? 'the tall man near the door'",["Phrase","Independent clause","Dependent clause","Complete sentence"],"Phrase","It has no verb. It's a noun phrase with a prepositional phrase modifier.",["phrase","clause","distinction"]))
ALL.append(q(192,"Easy","Is this a phrase or a clause? 'She finished the report'",["Phrase","Independent clause","Dependent clause","Complete sentence"],"Independent clause","It has a subject (She), a verb (finished), and expresses a complete thought.",["phrase","clause","distinction"]))
ALL.append(q(193,"Easy","Is this a phrase or a clause? 'running through the park'",["Phrase","Independent clause","Dependent clause","Complete sentence"],"Phrase","'Running' is a participle (not a finite verb), and there's no subject. It's a participial phrase.",["phrase","clause","distinction"]))
ALL.append(q(194,"Easy","Is this a phrase or a clause? 'when the bell rings'",["Phrase","Independent clause","Dependent clause","Complete sentence"],"Dependent clause","It has a subject (bell) and verb (rings) but begins with 'when' — incomplete thought.",["phrase","clause","distinction"]))
ALL.append(q(195,"Easy","Is this a phrase or a clause? 'to finish the assignment'",["Phrase","Independent clause","Dependent clause","Complete sentence"],"Phrase","It's an infinitive phrase — 'to finish' is not a finite verb.",["phrase","clause","distinction"]))
ALL.append(q(196,"Easy","Is this a phrase or a clause? 'although he tried his best'",["Phrase","Independent clause","Dependent clause","Complete sentence"],"Dependent clause","Subject (he) + verb (tried) + subordinator 'although' = dependent clause.",["phrase","clause","distinction"]))
ALL.append(q(197,"Easy","What type of sentence error is this? 'The report is due tomorrow the staff is working overtime.'",["Fragment","Run-on sentence","Correct sentence","Comma splice"],"Run-on sentence","Two independent clauses are fused without any punctuation between them.",["run-on","sentence error"]))
ALL.append(q(198,"Easy","What type of sentence error is this? 'Because the office was closed.'",["Fragment","Run-on sentence","Correct sentence","Comma splice"],"Fragment","It's a dependent clause standing alone — no independent clause to complete the thought.",["fragment","sentence error"]))
ALL.append(q(199,"Easy","What type of sentence error is this? 'She passed the exam, she was very happy.'",["Fragment","Run-on sentence","Correct sentence","Comma splice"],"Comma splice","Two independent clauses joined by only a comma — needs a conjunction or semicolon.",["comma splice","sentence error"]))
ALL.append(q(200,"Easy","What type of sentence error is this? 'Walking to school every morning.'",["Fragment","Run-on sentence","Correct sentence","Comma splice"],"Fragment","No subject and no finite verb. 'Walking' is a participle, not a complete verb.",["fragment","sentence error"]))

