# --- Subject in Complex Sentences (Medium 201-230) ---
ALL.append(q(201,"Medium","What is the simple subject of the main clause? 'The employees who attended the seminar received certificates.'",["employees","seminar","certificates","who"],"employees","The main clause is 'The employees...received certificates.' Who received? → employees. 'Who attended the seminar' is a relative clause modifier.",["subject","relative clause","main clause"]))
ALL.append(q(202,"Medium","What is the simple subject? 'The cost of the materials has increased significantly.'",["cost","materials","increased","significantly"],"cost","'Of the materials' is a prepositional phrase. The subject is never inside a prepositional phrase. What has increased? → cost.",["subject","prepositional phrase trap"]))
ALL.append(q(203,"Medium","What is the simple subject? 'One of the applicants was selected for the position.'",["One","applicants","position","selected"],"One","'Of the applicants' is a prepositional phrase. Who was selected? → One.",["subject","prepositional phrase trap"]))
ALL.append(q(204,"Medium","What is the simple subject? 'The results of the investigation were released to the public.'",["results","investigation","public","released"],"results","'Of the investigation' is a prepositional phrase. What were released? → results.",["subject","prepositional phrase trap"]))
ALL.append(q(205,"Medium","What is the simple subject? 'Each of the students has submitted a project proposal.'",["Each","students","proposal","submitted"],"Each","'Of the students' is a prepositional phrase. Who has submitted? → Each.",["subject","prepositional phrase trap"]))
ALL.append(q(206,"Medium","What is the simple subject? 'The box of chocolates was left on the counter.'",["box","chocolates","counter","left"],"box","'Of chocolates' is a prepositional phrase. What was left? → box.",["subject","prepositional phrase trap"]))
ALL.append(q(207,"Medium","What is the simple subject? 'Neither the manager nor the supervisors were informed.'",["manager","supervisors","Neither","informed"],"supervisors","In 'neither...nor' constructions, the verb agrees with the nearer subject. The compound subject is 'Neither the manager nor the supervisors,' but the simple subject closest to the verb is 'supervisors.'",["subject","compound subject","correlative conjunction"]))
ALL.append(q(208,"Medium","What is the simple subject? 'The collection of rare stamps belongs to the museum.'",["collection","stamps","museum","belongs"],"collection","'Of rare stamps' is a prepositional phrase. What belongs? → collection.",["subject","prepositional phrase trap"]))
ALL.append(q(209,"Medium","What is the simple subject? 'Several members of the committee have resigned.'",["members","committee","Several","resigned"],"members","'Of the committee' is a prepositional phrase. Who have resigned? → members. 'Several' is a modifier.",["subject","prepositional phrase trap"]))
ALL.append(q(210,"Medium","What is the simple subject? 'The quality of the products determines customer satisfaction.'",["quality","products","satisfaction","determines"],"quality","'Of the products' is a prepositional phrase. What determines? → quality.",["subject","prepositional phrase trap"]))
ALL.append(q(211,"Medium","What is the simple subject? 'Behind the old building stands a beautiful garden.'",["building","stands","garden","Behind"],"garden","This is an inverted sentence. Rearranged: 'A beautiful garden stands behind the old building.' What stands? → garden.",["subject","inverted sentence"]))
ALL.append(q(212,"Medium","What is the simple subject? 'Here are the documents you requested.'",["Here","documents","requested","are"],"documents","'Here' is an adverb, not a subject. What are here? → documents.",["subject","inverted sentence","expletive"]))
ALL.append(q(213,"Medium","What is the simple subject? 'There were several complaints about the new policy.'",["There","complaints","policy","were"],"complaints","'There' is an expletive (placeholder), not the subject. What were there? → complaints.",["subject","expletive","there"]))
ALL.append(q(214,"Medium","What is the simple subject? 'Among the candidates was a former government official.'",["candidates","was","official","Among"],"official","Inverted sentence. Rearranged: 'A former government official was among the candidates.' Who was? → official.",["subject","inverted sentence"]))
ALL.append(q(215,"Medium","What is the simple subject? 'The teacher, along with her students, is attending the conference.'",["teacher","students","conference","attending"],"teacher","'Along with her students' is a parenthetical phrase — it does not change the subject. Who is attending? → teacher.",["subject","parenthetical phrase"]))

ALL.append(q(216,"Medium","What is the simple subject? 'The president, together with the cabinet members, has approved the measure.'",["president","members","measure","approved"],"president","'Together with the cabinet members' is parenthetical. Who has approved? → president.",["subject","parenthetical phrase"]))
ALL.append(q(217,"Medium","What is the simple subject? 'Every one of the employees was given a performance evaluation.'",["one","employees","evaluation","given"],"one","'Of the employees' is a prepositional phrase. Who was given? → one.",["subject","prepositional phrase trap"]))
ALL.append(q(218,"Medium","What is the simple subject? 'The number of applicants has doubled this year.'",["number","applicants","year","doubled"],"number","'Of applicants' is a prepositional phrase. What has doubled? → number.",["subject","prepositional phrase trap"]))
ALL.append(q(219,"Medium","What is the simple subject? 'Both the teacher and the principal were present at the ceremony.'",["teacher","principal","Both","ceremony"],"Both","'Both...and' creates a compound subject. The core word is 'Both' (referring to teacher and principal together).",["subject","compound subject","correlative conjunction"]))
ALL.append(q(220,"Medium","What is the simple subject? 'The stack of papers on the desk needs to be filed.'",["stack","papers","desk","needs"],"stack","'Of papers' and 'on the desk' are prepositional phrases. What needs? → stack.",["subject","prepositional phrase trap"]))
ALL.append(q(221,"Medium","What is the complete subject? 'The newly appointed director of the finance department addressed the staff.'",["director","The newly appointed director of the finance department","The newly appointed director","staff"],"The newly appointed director of the finance department","The complete subject includes the noun and ALL its modifiers, including prepositional phrases.",["complete subject","identification"]))
ALL.append(q(222,"Medium","What is the complete subject? 'Several of the documents submitted last week contain errors.'",["Several of the documents submitted last week","documents","Several","errors"],"Several of the documents submitted last week","Everything before the verb 'contain' is the complete subject.",["complete subject","identification"]))
