# --- Sentence Completeness and Error Identification (Medium 306-350) ---
ALL.append(q(306,"Medium","Which sentence is grammatically complete and correct?",["Although the committee approved the budget, the project was delayed.","Although the committee approved the budget.","The committee approved the budget, the project was delayed.","Approved the budget and started the project."],"Although the committee approved the budget, the project was delayed.","It has a dependent clause + independent clause = complete complex sentence.",["complete sentence","complex sentence"]))
ALL.append(q(307,"Medium","Which sentence is grammatically complete and correct?",["Because she studied hard, she passed the exam.","Because she studied hard.","She studied hard, she passed the exam.","Studied hard and passed the exam."],"Because she studied hard, she passed the exam.","Dependent clause + independent clause = complete complex sentence.",["complete sentence","complex sentence"]))
ALL.append(q(308,"Medium","Which sentence contains a comma splice?",["The meeting ended early; everyone went home.","The meeting ended early, and everyone went home.","The meeting ended early, everyone went home.","Although the meeting ended early, everyone stayed."],"The meeting ended early, everyone went home.","Two independent clauses joined by only a comma — needs a conjunction or semicolon.",["comma splice","sentence error"]))
ALL.append(q(309,"Medium","Which sentence contains a comma splice?",["She finished the report, so she left early.","She finished the report; she left early.","She finished the report, she left early.","After she finished the report, she left early."],"She finished the report, she left early.","Two independent clauses joined by only a comma.",["comma splice","sentence error"]))
ALL.append(q(310,"Medium","Which sentence is a run-on (fused sentence)?",["The deadline is tomorrow, so we must hurry.","The deadline is tomorrow we must hurry.","The deadline is tomorrow; we must hurry.","Because the deadline is tomorrow, we must hurry."],"The deadline is tomorrow we must hurry.","Two independent clauses with no punctuation or conjunction between them.",["run-on","fused sentence"]))
ALL.append(q(311,"Medium","Which option correctly fixes this run-on? 'The policy was effective it reduced complaints by 40%.'",["The policy was effective, it reduced complaints by 40%.","The policy was effective; it reduced complaints by 40%.","The policy was effective it, reduced complaints by 40%.","The policy was effective and, it reduced complaints by 40%."],"The policy was effective; it reduced complaints by 40%.","A semicolon correctly joins two related independent clauses.",["run-on","correction","semicolon"]))
ALL.append(q(312,"Medium","Which option correctly fixes this fragment? 'Because the office was closed for renovation.'",["Because the office was closed for renovation, the staff worked from home.","Because, the office was closed for renovation.","The office was closed for renovation because.","Because the office was closed, for renovation."],"Because the office was closed for renovation, the staff worked from home.","Adding an independent clause completes the thought.",["fragment","correction"]))
ALL.append(q(313,"Medium","Which sentence has correct structure?",["The manager he approved the budget.","The manager approved the budget.","The manager, he approved the budget.","Approved the budget the manager."],"The manager approved the budget.","Clear S-V-O structure. The others have double subjects or missing/garbled subjects.",["correct structure","double subject"]))
ALL.append(q(314,"Medium","Which sentence has a structural error?",["The report was submitted on time.","She completed the assignment before the deadline.","The new policy regarding employee benefits.","The committee approved the proposal unanimously."],"The new policy regarding employee benefits.","No verb — it's a noun phrase (fragment), not a sentence.",["fragment","structural error"]))
