ALL.append(q(441,"Hard","How many clauses are in: 'The manager who was recently promoted announced that the company would expand its operations to provinces where demand has been growing steadily'?",["Two","Three","Four","Five"],"Four","(1) The manager...announced (main) (2) who was recently promoted (relative) (3) that the company would expand (noun) (4) where demand has been growing (relative).",["clause count","complex"]))
