ALL.append(q(444,"Hard","Identify the type of the clause 'that the auditor discovered' in: 'The discrepancies that the auditor discovered were reported to management.'",["Adjective clause","Adverb clause","Noun clause in apposition","Noun clause as direct object"],"Adjective clause","'That' is a relative pronoun functioning as the DO of 'discovered' inside the clause. It modifies 'discrepancies.'",["adjective clause","relative clause","distinction"]))
ALL.append(q(445,"Hard","What is the difference between the 'that' clauses in these sentences? (A) 'The fact that he resigned surprised us.' (B) 'The man that resigned was my colleague.'",["Both are adjective clauses.","Both are noun clauses.","A is a noun clause (appositive); B is an adjective clause.","A is an adjective clause; B is a noun clause."],"A is a noun clause (appositive); B is an adjective clause.","In A, 'that he resigned' explains 'fact' (appositive). In B, 'that resigned' modifies 'man' (relative clause — 'that' = who).",["that clause","distinction","appositive vs relative"]))
