ALL.append(q(447,"Hard","In 'It is essential that every employee be informed of the changes,' what is the function of the 'that' clause?",["Subject","Direct object","Subject complement","Delayed subject (in apposition to 'It')"],"Delayed subject (in apposition to 'It')","The 'that' clause is the logical/delayed subject. 'It' is a placeholder.",["noun clause","delayed subject","expletive"]))
ALL.append(q(448,"Hard","Identify the adverbial clause and its type in: 'The project was completed ahead of schedule because the team worked overtime every day.'",["'because the team worked overtime every day' — cause/reason","'ahead of schedule' — manner","'every day' — time","'The project was completed' — result"],"'because the team worked overtime every day' — cause/reason","The clause begins with 'because' and tells why the project was completed.",["adverb clause","cause","identification"]))
