ALL.append(q(450,"Hard","Identify the adverbial clause and its type in: 'He spoke so softly that nobody could hear him.'",["'that nobody could hear him' — result","'so softly' — manner","'nobody could hear him' — cause","'He spoke' — main clause"],"'that nobody could hear him' — result","'So...that' introduces a result clause.",["adverb clause","result","identification"]))
ALL.append(q(451,"Hard","What is the function of 'where the incident occurred' in: 'The police cordoned off the area where the incident occurred'?",["Noun clause (subject)","Noun clause (direct object)","Adjective clause (modifies 'area')","Adverb clause (place)"],"Adjective clause (modifies 'area')","'Where the incident occurred' modifies the noun 'area' — tells which area. It's a relative clause.",["adjective clause","relative clause","where"]))
