ALL.append(q(453,"Hard","What is the function of 'when the policy takes effect' in: 'The question is when the policy takes effect'?",["Noun clause (subject)","Noun clause (subject complement)","Adjective clause","Adverb clause (time)"],"Noun clause (subject complement)","After the linking verb 'is,' the clause renames 'question.'",["noun clause","subject complement","when"]))
