ALL.append(q(525,"Hard","CSE-style: Which sentence has a misplaced modifier?",["She almost finished all the reports.","She finished almost all the reports.","Almost she finished all the reports.","She finished all the almost reports."],"She almost finished all the reports.","'Almost' modifies 'finished' (she nearly finished) when the intended meaning is 'almost all.' Correct: 'She finished almost all the reports.'",["misplaced modifier","CSE-style"]))
ALL.append(q(526,"Hard","CSE-style: Identify the structural error: 'The manager not only approved the budget but also the new hiring plan.'",["Comma splice","Fragment","Faulty parallelism with correlative conjunction","Run-on sentence"],"Faulty parallelism with correlative conjunction","'Not only' precedes a verb phrase, but 'but also' precedes a noun phrase. Fix: 'approved not only the budget but also the new hiring plan.'",["parallelism","correlative conjunction","CSE-style"]))
ALL.append(q(527,"Hard","CSE-style: Identify the structural error: 'The report was comprehensive, detailed, and it covered all the necessary topics.'",["Fragment","Comma splice","Faulty parallelism (adjective, adjective, clause)","Run-on"],"Faulty parallelism (adjective, adjective, clause)","The series mixes adjectives with a clause. Fix: 'comprehensive, detailed, and thorough' or restructure.",["parallelism","series","CSE-style"]))
ALL.append(q(528,"Hard","CSE-style: Which revision correctly fixes: 'Walking through the park, the flowers were beautiful'?",["Walking through the park, she noticed the beautiful flowers.","The flowers were beautiful, walking through the park.","Walking through the park, it was noticed that the flowers were beautiful.","The flowers, walking through the park, were beautiful."],"Walking through the park, she noticed the beautiful flowers.","The participial phrase now correctly modifies 'she' (the one walking).",["dangling modifier","correction","CSE-style"]))
ALL.append(q(529,"Hard","CSE-style: Which revision correctly fixes: 'The proposal was rejected by the committee, it did not meet the minimum requirements'?",["The proposal was rejected by the committee; it did not meet the minimum requirements.","The proposal was rejected by the committee it did not meet the minimum requirements.","The proposal was rejected by the committee, and, it did not meet the minimum requirements.","The proposal was rejected, by the committee it did not meet the minimum requirements."],"The proposal was rejected by the committee; it did not meet the minimum requirements.","Semicolon correctly separates two related independent clauses.",["comma splice","correction","CSE-style"]))
ALL.append(q(530,"Hard","CSE-style: Which revision correctly fixes: 'Although the team worked overtime and the project was still not completed on time'?",["Although the team worked overtime, the project was still not completed on time.","Although the team worked overtime and the project was still not completed on time, they tried.","The team worked overtime, although the project was still not completed on time.","Although the team worked overtime; the project was still not completed on time."],"Although the team worked overtime, the project was still not completed on time.","Removing 'and' creates a proper dependent clause + independent clause structure.",["fragment","correction","CSE-style"]))
ALL.append(q(531,"Hard","CSE-style: In 'The documents, which were filed incorrectly, need to be reorganized,' can the relative clause be removed without changing the core meaning?",["Yes — it is nonrestrictive (extra information).","No — it is restrictive (essential to identify which documents).","No — removing it creates a fragment.","Yes — but only if you also remove the commas."],"Yes — it is nonrestrictive (extra information).","Commas signal a nonrestrictive clause — it adds info but isn't essential to identify the documents.",["nonrestrictive","removal test","CSE-style"]))
ALL.append(q(532,"Hard","CSE-style: In 'The documents that were filed incorrectly need to be reorganized,' can the relative clause be removed without changing the core meaning?",["Yes — it is nonrestrictive.","No — it is restrictive (identifies WHICH documents).","No — removing it creates a fragment.","Yes — the sentence still makes sense."],"No — it is restrictive (identifies WHICH documents).","No commas = restrictive. It specifies which documents (only the incorrectly filed ones).",["restrictive","removal test","CSE-style"]))
ALL.append(q(533,"Hard","CSE-style: What is the structural issue? 'The reason is because the budget was insufficient.'",["Fragment","Comma splice","Redundancy ('reason...because' is redundant)","No error"],"Redundancy ('reason...because' is redundant)","'The reason is because' is redundant. Correct: 'The reason is that the budget was insufficient.'",["redundancy","reason is because","CSE-style"]))
ALL.append(q(534,"Hard","CSE-style: What is the structural issue? 'Being that the office was closed, we worked from home.'",["Fragment","Nonstandard conjunction ('Being that' is informal/incorrect)","Comma splice","No error"],"Nonstandard conjunction ('Being that' is informal/incorrect)","'Being that' is nonstandard. Use 'Because' or 'Since' instead.",["nonstandard","conjunction","CSE-style"]))
ALL.append(q(535,"Hard","CSE-style: Identify the correctly punctuated compound-complex sentence.",["Although the budget was limited the team completed the project, and they received commendation.","Although the budget was limited, the team completed the project, and they received commendation.","Although the budget was limited, the team completed the project and they received commendation.","Although, the budget was limited, the team completed the project, and they received commendation."],"Although the budget was limited, the team completed the project, and they received commendation.","Comma after dependent clause, comma + conjunction between independent clauses.",["compound-complex","punctuation","CSE-style"]))
ALL.append(q(536,"Hard","CSE-style: In 'The manager expects not only that the report be submitted on time but also that it be thoroughly reviewed,' what are the compound elements?",["Two subjects","Two predicates","Two noun clauses (direct objects)","Two adverb clauses"],"Two noun clauses (direct objects)","'Not only that...but also that...' joins two noun clauses, both serving as objects of 'expects.'",["compound","noun clauses","correlative"]))
ALL.append(q(537,"Hard","CSE-style: What is the function of 'to have been completed before the audit' in: 'The report was supposed to have been completed before the audit'?",["Subject","Direct object","Subject complement","Part of the verb phrase (infinitive complement)"],"Part of the verb phrase (infinitive complement)","'Was supposed to have been completed' functions as a complex verb phrase (passive + perfect infinitive).",["infinitive","verb phrase","complex"]))
