ALL.append(q(539,"Hard","CSE-style: In 'There appear to be several discrepancies in the report,' what is the logical subject?",["There","discrepancies","report","appear"],"discrepancies","'There' is an expletive. The logical subject is 'several discrepancies.'",["expletive","logical subject","CSE-style"]))
ALL.append(q(540,"Hard","CSE-style: In 'It was reported that the funds had been misappropriated,' what is the logical subject of 'reported'?",["It","funds","Someone/people (implied agent)","that the funds had been misappropriated"],"Someone/people (implied agent)","Passive voice hides the agent. Someone reported it. The 'that' clause is the logical object.",["passive","implied agent","CSE-style"]))

