ALL.append(q(545,"Hard","CSE-style: In 'The employees were made to undergo additional training,' what voice and structure is used?",["Active voice, simple sentence","Passive voice with bare infinitive","Passive voice with to-infinitive (causative passive)","Active voice with object complement"],"Passive voice with to-infinitive (causative passive)","Active: 'Someone made the employees undergo...' (bare infinitive). Passive adds 'to': 'were made to undergo.'",["passive","causative","to-infinitive"]))
