ALL.append(q(548,"Hard","CSE-style: In 'So impressed was the panel that they offered her the position immediately,' what triggers the inversion?",["The question form","The fronted adverb 'So impressed'","The passive voice","The conjunction 'that'"],"The fronted adverb 'So impressed'","Fronting 'So + adjective/adverb' triggers subject-auxiliary inversion in formal English.",["inversion","fronted adverb","CSE-style"]))
